import{_ as r,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"🔬 科学快报 | 2026年8月24日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-24.md","filePath":"science-log/src/reconstructed/2026-08-24.md"}'),e={name:"science-log/src/reconstructed/2026-08-24.md"};function a(g,t,i,l,c,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="🔬-科学快报-2026年8月24日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月24日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月24日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月24日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-08-24 为<strong>周一</strong>。CrossRef 当日命中：Nature（0028-0836）仅 6 条，<strong>全部为 <code>10.1038/d41586-…</code> 新闻/Briefing，无一条 <code>s41586</code> 研究论文</strong>（该周的研究论文集中在 08-19 与 08-26）；Science 系（10.1126）当日仅 2 条，均为 <code>10.1126/science.z…</code>／Adviser 新闻稿；<strong>PNAS（0027-8424）当日命中 36 条研究论文</strong>，为当日唯一充足来源。故<strong>科学 5 篇全部取自 PNAS 当日（<code>published</code> = 2026-08-24）研究论文</strong>；<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（submittedDate <code>[202608240000 TO 202608242359]</code>，命中 30 篇，触及 max_results 上限）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-06</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧫-mettl3–rexo2-轴失守-线粒体双链-rna-泄漏点燃上皮-i-型干扰素" tabindex="-1">🧫 METTL3–REXO2 轴失守：线粒体双链 RNA 泄漏点燃上皮 I 型干扰素 <a class="header-anchor" href="#🧫-mettl3–rexo2-轴失守-线粒体双链-rna-泄漏点燃上皮-i-型干扰素" aria-label="Permalink to &quot;🧫 METTL3–REXO2 轴失守：线粒体双链 RNA 泄漏点燃上皮 I 型干扰素&quot;">​</a></h3><p><strong>Loss of epitranscriptomic mitochondrial RNA surveillance drives epithelial type I interferon and inflammation in autoimmunity</strong><em>PNAS（2026）</em></p><p>干燥综合征（SjD）与系统性红斑狼疮中，上皮细胞长期处于 I 型干扰素（IFN-I）激活状态，但&quot;到底是谁点燃了它&quot;始终缺直接证据。本文给出了一条<strong>表观转录组 → 线粒体 → 先天免疫</strong>的完整链条：RNA 甲基转移酶 <strong>METTL3</strong> 通过 <strong>m⁶A</strong> 修饰稳定 <strong>REXO2</strong> mRNA，而 REXO2 是降解<strong>线粒体双链 RNA（mt-dsRNA）<strong>的核酸外切酶。抑制 METTL3 会拉低 REXO2，导致 mt-dsRNA 堆积、IFN-I 信号放大并引发炎症；SjD 患者唾液腺组织的单细胞与 bulk 转录组、免疫荧光均显示 <strong>REXO2 表达下降、IFN-I 特征升高</strong>，自发性 SjD 小鼠模型的上皮细胞同样 down-regulation。最关键的</strong>可干预性</strong>：补充<strong>甲基供体</strong>可恢复 REXO2 并压低 IFN 激活——这提示 m⁶A 写入是一个可药物的检查点，而非不可逆的遗传缺陷。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2534325123" target="_blank" rel="noreferrer">10.1073/pnas.2534325123</a></p><h3 id="🦠-免疫逃逸不是偶然-hla-i-类逃逸在人群尺度上塑造-sars-cov-2-演化" tabindex="-1">🦠 免疫逃逸不是偶然：HLA-I 类逃逸在人群尺度上塑造 SARS-CoV-2 演化 <a class="header-anchor" href="#🦠-免疫逃逸不是偶然-hla-i-类逃逸在人群尺度上塑造-sars-cov-2-演化" aria-label="Permalink to &quot;🦠 免疫逃逸不是偶然：HLA-I 类逃逸在人群尺度上塑造 SARS-CoV-2 演化&quot;">​</a></h3><p><strong>HLA class I escape drives the evolution of SARS-CoV-2 in human populations</strong><em>PNAS（2026）</em></p><p>细胞毒性 T 细胞（CTL）逃逸对新冠病毒演化到底有多大权重，长期有争议。本文用群体遗传学方法给出量化答案：在<strong>变异株特征突变中约 35%</strong>、在<strong>其后累积的全部病毒突变中约 39%</strong>，都会降低病毒表位经 <strong>HLA-I 类</strong>分子的呈递——即直接服务于<strong>逃逸</strong>。更强的证据是<strong>地理与宿主基因型的耦合</strong>：能够逃逸<strong>更常见 HLA 等位基因</strong>的突变，会在该等位基因频率更高的国家达到更高频率，说明选择压力来自<strong>当地人群的免疫遗传构成</strong>本身。作者还发现，普通人群传播链中积累的突变与人群 HLA-I 等位基因频率的匹配程度，<strong>不亚于</strong>免疫抑制个体长期感染中获得的突变——这意味着逃逸选择并非只发生在免疫缺陷宿主中。CTL 逃逸应被正式纳入病毒演化的选择项，而不只是体液免疫的注脚。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2619192123" target="_blank" rel="noreferrer">10.1073/pnas.2619192123</a></p><h3 id="🧠-氯离子不助推、只-搭骨架-sert-转运蛋白的结构辅因子新解" tabindex="-1">🧠 氯离子不助推、只&quot;搭骨架&quot;：SERT 转运蛋白的结构辅因子新解 <a class="header-anchor" href="#🧠-氯离子不助推、只-搭骨架-sert-转运蛋白的结构辅因子新解" aria-label="Permalink to &quot;🧠 氯离子不助推、只&quot;搭骨架&quot;：SERT 转运蛋白的结构辅因子新解&quot;">​</a></h3><p><strong>The role of chloride ions in serotonin transport</strong><em>PNAS（2026）</em></p><p>血清素转运体 <strong>SERT</strong> 把 5-HT⁺ 泵入细胞，依靠 <strong>Na⁺ 同向转运</strong>与 <strong>K⁺ 反向转运</strong>耦合供能。细胞外 <strong>Cl⁻</strong> 同样不可缺少，但&quot;Cl⁻ 是否被化学计量共转运&quot;争论数十年。本文用实验加模拟把它判为<strong>否</strong>：改变 Cl⁻ 梯度<strong>不影响 5-HT⁺ 的累积</strong>，说明 Cl⁻ <strong>不提供驱动力</strong>、不构成化学计量同向转运。Cl⁻ 真正的作用是<strong>调节构象</strong>——它对 Na⁺ 介导的胞质侧通路关闭只有很小影响，却<strong>显著降低胞外侧通路残基的可及性</strong>，即稳定<strong>外向（outward-facing）状态</strong>；模拟显示 Cl⁻ 与<strong>已结合的 Na⁺ 强烈相互作用</strong>，并稳固胞外侧的螺旋堆积。结论是一个干净的重新定义：<strong>Cl⁻ 是必需的&quot;结构辅因子&quot;</strong>——通过提高 Na⁺ 亲和力与螺旋间相互作用，让转运所必需的构象转换得以发生，而非作为能量耦合的一环。这对以 SERT 为靶点的抗抑郁药设计有直接含义：别再把 Cl⁻ 位点当作能量备份，它更像是机械关节的垫片。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605760123" target="_blank" rel="noreferrer">10.1073/pnas.2605760123</a></p><h3 id="☄️-太阳系最早的固体记住了星云磁场-cai-古地磁给出-150–600-μt" tabindex="-1">☄️ 太阳系最早的固体记住了星云磁场：CAI 古地磁给出 150–600 μT <a class="header-anchor" href="#☄️-太阳系最早的固体记住了星云磁场-cai-古地磁给出-150–600-μt" aria-label="Permalink to &quot;☄️ 太阳系最早的固体记住了星云磁场：CAI 古地磁给出 150–600 μT&quot;">​</a></h3><p><strong>Paleomagnetic evidence for a nebular magnetic field from calcium-aluminum-rich inclusions</strong><em>PNAS（2026）</em></p><p>行星形成的最初阶段发生在原行星盘内——盘物质一边吸积到原恒星上，一边被仍在坠落的包层包裹，同时生成<strong>钙铝包体（CAI）<strong>这类高凝聚温度固体，它们是已知</strong>太阳系最古老的固体</strong>。这一阶段究竟是<strong>磁</strong>主导吸积还是<strong>引力</strong>主导，一直没有实测依据。本文对 CAI 做<strong>古地磁测量</strong>，得到约 <strong>150–600 μT</strong> 的星云磁场强度记录。这个量级足以让<strong>磁制动/磁离心</strong>在盘吸积中扮演关键角色，同时也与&quot;磁场在太阳系形成最早期把极内盘加热到 <strong>10³ K</strong>&quot;的图景自洽。方法上的意义同样重要：CAI 作为最早凝结的矿物，把当时磁场的&quot;快照&quot;锁进了它的剩磁里，使几十亿年后的实验室测量可以反推<strong>行星摇篮的物理条件</strong>。这为原行星盘吸积模型提供了一个此前缺失的、来自实物而非模拟的约束。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2521660123" target="_blank" rel="noreferrer">10.1073/pnas.2521660123</a></p><h3 id="🌪️-混沌系统的机器学习闭合必须-随机化-确定性损失有数学上的死结" tabindex="-1">🌪️ 混沌系统的机器学习闭合必须&quot;随机化&quot;：确定性损失有数学上的死结 <a class="header-anchor" href="#🌪️-混沌系统的机器学习闭合必须-随机化-确定性损失有数学上的死结" aria-label="Permalink to &quot;🌪️ 混沌系统的机器学习闭合必须&quot;随机化&quot;：确定性损失有数学上的死结&quot;">​</a></h3><p><strong>Stochasticity and probabilistic trajectory scoring are essential for data-driven closures of chaotic systems</strong><em>PNAS（2026）</em></p><p>粗粒化模型必然忽略未分辨自由度，由此引入<strong>结构性模型误差</strong>，既压低可预报性也扭曲长期统计。主流数据驱动&quot;闭合&quot;只在<strong>单步预测误差</strong>上训练，隐含假设马尔可夫性；较新的做法改为在<strong>有限长度轨迹</strong>上优化损失——但如果用的是<strong>确定性逐点损失</strong>，本文<strong>证明</strong>它存在一个根本性数学退化：在混沌轨迹上优化逐点确定性损失（含但不限于均方误差）会<strong>压制预测方差</strong>，导致长时间积分中<strong>物理变率丢失</strong>。出路是改用<strong>严格适当评分规则（strictly proper scoring rules）</strong>：把目标从&quot;某条真实轨迹&quot;换成&quot;<strong>预报分布</strong>&quot;，就消除了对预测展宽的惩罚，使长时效最优解<strong>对齐系统的遍历不变测度</strong>。作者以<strong>准地转湍流</strong>为算例验证。这条结论对气候、海洋与工程中的一切粗粒化建模都是硬约束：想保住长程统计，就不能用点对点的确定性目标函数去训练混沌系统。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2609143123" target="_blank" rel="noreferrer">10.1073/pnas.2609143123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="📊-把数据配比当-混料实验-用-scheffe-响应曲面-i-最优设计省掉-25-代理训练" tabindex="-1">📊 把数据配比当&quot;混料实验&quot;：用 Scheffé 响应曲面 + I-最优设计省掉 25% 代理训练 <a class="header-anchor" href="#📊-把数据配比当-混料实验-用-scheffe-响应曲面-i-最优设计省掉-25-代理训练" aria-label="Permalink to &quot;📊 把数据配比当&quot;混料实验&quot;：用 Scheffé 响应曲面 + I-最优设计省掉 25% 代理训练&quot;">​</a></h3><p><strong>Data Mixing as Mixture Experiment: Response Surface Methodology and Optimal Design for Large Language Model Pretraining</strong><em>arXiv:2608.23922（cs.AI，2026）</em></p><p>大模型预训练的核心设计问题是<strong>固定 token 预算下各领域分多少</strong>。主流的&quot;代理法&quot;先在小模型上跑若干候选配比、拟合响应模型、再外推到大规模。本文指出这一流程本质是经典的<strong>混料实验（mixture experiment）</strong>：领域 = 混料分量、token 占比 = 分量比例、每次代理训练 = 一个试验点、验证损失 = <strong>概率单纯形上的响应曲面</strong>。作者用<strong>稀疏二阶 Scheffé 模型</strong>刻画曲面，并为代理实验构造<strong>模型稳健的 𝓘-最优设计</strong>。以 <strong>RegMix</strong> 为实证案例，Scheffé 分析揭示<strong>领域价值是强关系型的</strong>——若干在可加效应下表现平庸的领域，通过与网络文本等的<strong>成对交互</strong>变得有利；稀疏 Scheffé 模型能在不同模型尺度上保持配比排序，且可分解出可加项与交互项。仿真显示，模型稳健 𝓘-最优设计在<strong>去掉约 25% 原始代理训练</strong>后仍能恢复正确排序。结论：数据配比不只是预测问题，更是<strong>实验设计问题</strong>——代理混合本身可以被&quot;设计&quot;出来以提升统计效率。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.23922" target="_blank" rel="noreferrer">2608.23922</a></p><h3 id="🏆-mars-按算法专题分科的-llm-接力-竞赛编程-pass-rate-提升-14-4-个百分点" tabindex="-1">🏆 MARS：按算法专题分科的 LLM 接力，竞赛编程 pass rate 提升 14.4 个百分点 <a class="header-anchor" href="#🏆-mars-按算法专题分科的-llm-接力-竞赛编程-pass-rate-提升-14-4-个百分点" aria-label="Permalink to &quot;🏆 MARS：按算法专题分科的 LLM 接力，竞赛编程 pass rate 提升 14.4 个百分点&quot;">​</a></h3><p><strong>MARS: Multi-Specialist LLM Relay System for Competitive Programming</strong><em>arXiv:2608.23918（cs.AI / EMNLP 2026）</em></p><p>现有竞赛编程多智能体流水线普遍采用<strong>通用</strong>的规划者/编码者/调试者角色，把&quot;选什么算法&quot;交给骨干模型自己决定——这正是失败模式的来源。<strong>MARS</strong> 是纯提示（prompt-only）框架：每个智能体是一个<strong>专题专家</strong>（动态规划、图论、字符串、几何……），并由<strong>算法理论语料上的 RAG</strong> 支撑。给定题目，检索先选出一个小型专家团队，首位（starter）写出 C++17 初稿，此后每一轮都在<strong>沙箱里跑公开样例</strong>，由当前激活的专家决定<strong>保留/修复/移交</strong>，并把结构化 packet 传给下一位；最后一轮 infrastructure-fixer 统一规整样板代码。在 <strong>CodeContests 测试集 + Gemma 4</strong> 上，MARS 达到 <strong>0.624 ± 0.006</strong> 通过率（每任务 <strong>2.3</strong> 个记录阶段），比直接提示<strong>高 14.4 个百分点</strong>，在墙钟成本低 <strong>3.3×</strong> 的情况下逼近 CodeSIM（0.731），且<strong>每任务 token 花费方差显著更小</strong>。代码已开源。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.23918" target="_blank" rel="noreferrer">2608.23918</a></p><h3 id="⚛️-绕开轨道对角化-神经算子直接学-kohn–sham-映射-实现准线性标度-dft" tabindex="-1">⚛️ 绕开轨道对角化：神经算子直接学 Kohn–Sham 映射，实现准线性标度 DFT <a class="header-anchor" href="#⚛️-绕开轨道对角化-神经算子直接学-kohn–sham-映射-实现准线性标度-dft" aria-label="Permalink to &quot;⚛️ 绕开轨道对角化：神经算子直接学 Kohn–Sham 映射，实现准线性标度 DFT&quot;">​</a></h3><p><strong>Learning the Kohn-Sham map with neural operators for quasi-linear scaling density functional theory</strong><em>arXiv:2608.23895（physics.chem-ph，2026）</em></p><p>Kohn–Sham 密度泛函理论是所有电子结构模拟的底座，但反复的<strong>轨道对角化</strong>带来 <strong>O(N³) 标度</strong>，把量子计算锁在中小尺度。轨道自由 DFT 想在不放弃 KS 精度的前提下消掉辅助轨道，解析与机器学习路线此前都没做到：学<strong>变分动能泛函</strong>病态（ill-conditioned），直接<strong>预测基态</strong>又外推极差。本文换掉学习目标——<strong>把 Kohn–Sham 映射本身当作学习对象</strong>：它把 KS 势直接映到对应密度与非相互作用动能，本该由对角化得到。作者用<strong>域不变的 SE(3) 等变傅里叶神经算子</strong>，在实空间网格上从势预测密度，实现稳定的<strong>准线性标度 SCF</strong>。在 <strong>8,504 个分子与固体</strong>上联合训练，单一模型可泛化到分布外的有机分子、绝缘体与金属，<strong>首次</strong>在不显式构造 KS 轨道的情况下跨这些体系收敛 SCF，并在密度、电子谱与结构可观测量上保持 KS-DFT 精度。线性标度 SCF 还允许在<strong>单张 GPU</strong> 上收敛含 <strong>82,500 个价电子</strong>的镁位错密度。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.23895" target="_blank" rel="noreferrer">2608.23895</a></p><h3 id="🧮-解释的数学理论-把-可解释-变成有访问假设、有保证、有失效模式的方法设计问题" tabindex="-1">🧮 解释的数学理论：把&quot;可解释&quot;变成有访问假设、有保证、有失效模式的方法设计问题 <a class="header-anchor" href="#🧮-解释的数学理论-把-可解释-变成有访问假设、有保证、有失效模式的方法设计问题" aria-label="Permalink to &quot;🧮 解释的数学理论：把&quot;可解释&quot;变成有访问假设、有保证、有失效模式的方法设计问题&quot;">​</a></h3><p><strong>A Mathematical Theory of Interpretation: Rational Entropy, Spectral Readout, and Confusability as a Resource</strong><em>arXiv:2608.23892（cs.IT，2026，博士论文节选）</em></p><p>本文是《解释的数学理论》（MTI）的节选核心，把<strong>解释</strong>定义为<strong>访问结构下的观察者相对谱测量</strong>，从而把&quot;解释&quot;从哲学口号变成<strong>方法设计问题</strong>：访问、查询、效用、介质四要素决定观察者能选择、指认、传达或<strong>拒绝</strong>什么。在学习不变的希尔伯特实现下，<strong>理性熵（Rational Entropy）<strong>度量跨知识、效用与介质三者的</strong>残余不确定性</strong>，作者在有限有效区制中完整刻画了它的零点集。一个反直觉结论涉及<strong>混淆度</strong>：成对混淆等价于<strong>均匀原子坍缩</strong>，但当存在唯一效用极大值时，即使其他零代价态仍未原子化，也能选定某个原子——这<strong>颠倒了混淆在零误差场景中的传统角色</strong>：在一个观察方向上的一致性即可排除未解决的多原子读法，而联合标签仍保持可识别性。相应的自由设计容量是除最小区块外所有方向预算之积；一个<strong>四条件判据</strong>刻画了有限对易码扇区上&quot;尖锐、可解码、介质忠实、顺序无关&quot;的读出，并在保证不成立时给出<strong>带类型的障碍</strong>。MTI 的定位是：为解释方法提供显式的访问假设、保证与失效模式。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.23892" target="_blank" rel="noreferrer">2608.23892</a></p><h3 id="🔐-签名合法-意图真实-agent-payments-protocol-v0-2-的系统性安全分析" tabindex="-1">🔐 签名合法≠意图真实：Agent Payments Protocol v0.2 的系统性安全分析 <a class="header-anchor" href="#🔐-签名合法-意图真实-agent-payments-protocol-v0-2-的系统性安全分析" aria-label="Permalink to &quot;🔐 签名合法≠意图真实：Agent Payments Protocol v0.2 的系统性安全分析&quot;">​</a></h3><p><strong>Beyond the Mandate: A Systematic Security Analysis of the Agent Payments Protocol (AP2)</strong><em>arXiv:2608.23858（cs.CR，2026）</em></p><p>Google 提出的 <strong>AP2</strong> 让 LLM 购物智能体<strong>代用户授权并执行支付</strong>，其签名的 Checkout / Payment Mandate 保护<strong>签名之后</strong>的交易数据完整性。但<strong>签名之前</strong>塑造交易的一切——<strong>A2A 智能体间消息</strong>与 <strong>MCP 工具调用</strong>——都在这层保护之外。此前工作已在 AP2 v0.1 中发现重放与提示注入；v0.2 修了一部分，却引入新能力与部署假设，需要重新分析。本文按角色、交易生命周期、部署架构与信任边界做系统分析：把生命周期划为<strong>五阶段</strong>、归纳<strong>五种部署架构</strong>；用 <strong>MAESTRO</strong> 框架建模 <strong>4 类威胁行为者、11 个攻击面、18 项对手能力、6 个攻击者目标</strong>，得到含<strong>48 条威胁、5 个攻击族</strong>的目录；用 <strong>AIVSS</strong> 评分后，有 <strong>8 条</strong>威胁在至少一种架构中达到 <strong>High 档</strong>。因不存在完整的公开 AP2 部署，作者自建覆盖全部五种架构的测试床，并给出 <strong>5 个 PoC</strong> 覆盖全部 8 条高风险威胁及其缓解；此外开发了<strong>部署感知扫描器</strong>，把适用威胁映射到静态检查、跨角色一致性检查与对抗性检查。核心结论一句话：<strong>合法的 mandate 签名本身，并不能保证在被操纵的预授权上下文下，代理交易仍反映用户真实意图。</strong></p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.23858" target="_blank" rel="noreferrer">2608.23858</a></p><blockquote><p>📅 日期：2026-08-24 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=r(e,[["render",a]]);export{u as __pageData,d as default};
